import json, subprocess, sys, os
def widths(strings, env=None):
    ref = "R" * 60
    objs = [{"Path": ref}] + [{"Path": s} for s in strings]
    inp = "\n".join(json.dumps(o, ensure_ascii=False) for o in objs)
    e = dict(os.environ); 
    if env: e.update(env)
    p = subprocess.run(["/workspace/executable"], input=inp.encode(), capture_output=True, env=e)
    lines = p.stdout.decode().split("\n")
    rows = [l for l in lines if l.startswith("| ")][1:]  # skip header
    res = []
    for s, l in zip(strings, rows[1:]):
        cell = l.split(" | ")[0][2:]  # content + padding
        assert cell.startswith(s), (cell, s)
        pad = len(cell) - len(s)
        res.append(60 - pad)
    return res
def decode(t):
    if '\\' in t:
        return t.encode('latin-1', 'backslashreplace').decode('unicode_escape')
    return t
if __name__ == "__main__":
    tests = [decode(t) for t in sys.argv[1:]]
    for s, w in zip(tests, widths(tests)):
        print(repr(s), [hex(ord(c)) for c in s], w)
EOF
