// Package textwidth computes the number of terminal cells a string occupies.
//
// Widths are computed per grapheme cluster: a cluster is as wide as its first
// rune that has a non-zero width. Rune widths come from tables that were
// derived by observing the reference implementation, with an optional
// "East Asian" mode in which ambiguous characters are treated as wide.
package textwidth

import (
	"os"
	"regexp"
	"strings"
)

// rng is an inclusive range of runes.
type rng struct {
	lo, hi rune
}

func inRanges(r rune, table []rng) bool {
	lo, hi := 0, len(table)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		e := table[mid]
		switch {
		case r < e.lo:
			hi = mid - 1
		case r > e.hi:
			lo = mid + 1
		default:
			return true
		}
	}
	return false
}

// Condition holds the settings that influence width computation.
type Condition struct {
	EastAsian bool
}

// Default is the condition initialised from the environment.
var Default = &Condition{EastAsian: IsEastAsianEnv()}

// RuneWidth returns the number of cells the rune occupies on its own.
func (c *Condition) RuneWidth(r rune) int {
	if r < 0 || r > 0x10FFFF {
		return 0
	}
	if inRanges(r, zeroWidth) {
		return 0
	}
	if c.EastAsian {
		if inRanges(r, wideWidthEastAsian) {
