// Package table renders rows of text as an ASCII table.
//
// Cells are wrapped to a maximum width, multi-line cells are supported, the
// header is centred and numeric cells are right aligned.
package table

import (
	"fmt"
	"io"
	"regexp"
	"strings"

	"github.com/psampaz/go-mod-outdated/internal/textwidth"
)

const (
	space        = " "
	newline      = "\n"
	maxCellWidth = 30
	wrapPenalty  = 100000
)

var (
	ansiEscape = regexp.MustCompile("\033\\[(?:[0-9]{1,3}(?:;[0-9]{1,3})*)?[m|K]")
	decimal    = regexp.MustCompile(`^-?(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d+)?$`)
)

// Borders controls which outer borders are drawn.
type Borders struct {
	Left, Right, Top, Bottom bool
}

// Table accumulates a header and rows and renders them.
type Table struct {
	out       io.Writer
	headers   [][]string
	rows      [][][]string
	colWidths []int
	rowHeight []int
	hdrHeight int

	center  string
	row     string
	column  string
	borders Borders
}

// New creates an empty table writing to out.
func New(out io.Writer) *Table {
	return &Table{
		out:     out,
		center:  "+",
		row:     "-",
		column:  "|",
		borders: Borders{Left: true, Right: true, Top: true, Bottom: true},
	}
}

// SetCenterSeparator sets the string drawn where lines intersect.
func (t *Table) SetCenterSeparator(s string) { t.center = s }

// SetBorders sets which outer borders are drawn.
func (t *Table) SetBorders(b Borders) { t.borders = b }

// SetHeader sets the header cells.
func (t *Table) SetHeader(keys []string) {
	t.headers = nil
	for i, k := range keys {
		lines := t.measure(k, i)
		if len(lines) > t.hdrHeight {
			t.hdrHeight = len(lines)
		}
		t.headers = append(t.headers, lines)
	}
}

// Append adds a row.
func (t *Table) Append(row []string) {
	cells := make([][]string, 0, len(row))
	height := 0
	for i, v := range row {
		lines := t.measure(v, i)
		if len(lines) > height {
			height = len(lines)
		}
		cells = append(cells, lines)
	}
	t.rows = append(t.rows, cells)
	t.rowHeight = append(t.rowHeight, height)
}

// measure wraps the cell content and records the column width.
func (t *Table) measure(str string, col int) []string {
	raw := strings.Split(str, newline)
	maxWidth := 0
	for _, line := range raw {
		if w := displayWidth(line); w > maxWidth {
			maxWidth = w
		}
	}
	if maxWidth > maxCellWidth {
		maxWidth = maxCellWidth
	}
	newMax := maxWidth
	lines := wrapString(strings.Join(raw, space), maxWidth)
	for _, line := range lines {
		if w := displayWidth(line); w > newMax {
			newMax = w
		}
	}
	for len(t.colWidths) <= col {
		t.colWidths = append(t.colWidths, 0)
	}
	if t.colWidths[col] < newMax {
		t.colWidths[col] = newMax
	}
	return lines
}

// Render writes the table.
func (t *Table) Render() {
	if t.borders.Top {
		t.printLine()
	}
	t.printHeader()
	for i, row := range t.rows {
		t.printRow(row, t.rowHeight[i])
	}
	if t.borders.Bottom {
		t.printLine()
	}
}

func (t *Table) printLine() {
	fmt.Fprint(t.out, t.center)
	for _, w := range t.colWidths {
		fmt.Fprintf(t.out, "%s%s%s%s", t.row, strings.Repeat(t.row, w), t.row, t.center)
	}
	fmt.Fprint(t.out, newline)
}

func (t *Table) printHeader() {
	if len(t.headers) == 0 {
		return
	}
	end := len(t.colWidths) - 1
	for x := 0; x < t.hdrHeight; x++ {
		if t.borders.Left {
			fmt.Fprint(t.out, t.column)
		} else {
			fmt.Fprint(t.out, space)
		}
		for y := 0; y <= end; y++ {
			h := ""
			if y < len(t.headers) && x < len(t.headers[y]) {
				h = t.headers[y][x]
			}
			h = title(h)
			pad := t.column
			if y == end && !t.borders.Left {
				pad = space
			}
			fmt.Fprintf(t.out, " %s %s", padCenter(h, t.colWidths[y]), pad)
		}
		fmt.Fprint(t.out, newline)
	}
	t.printLine()
}

func (t *Table) printRow(cells [][]string, height int) {
	total := len(cells)
	for i := range cells {
		for len(cells[i]) < height {
			cells[i] = append(cells[i], "  ")
		}
	}
	for x := 0; x < height; x++ {
		for y := 0; y < total; y++ {
			if !t.borders.Left && y == 0 {
				fmt.Fprint(t.out, space)
			} else {
				fmt.Fprint(t.out, t.column)
			}
			fmt.Fprint(t.out, space)
			str := cells[y][x]
			if decimal.MatchString(strings.TrimSpace(str)) {
				fmt.Fprint(t.out, padLeft(str, t.colWidths[y]))
			} else {
				fmt.Fprint(t.out, padRight(str, t.colWidths[y]))
			}
			fmt.Fprint(t.out, space)
		}
		if t.borders.Left {
			fmt.Fprint(t.out, t.column)
		} else {
			fmt.Fprint(t.out, space)
		}
		fmt.Fprint(t.out, newline)
	}
}

// title normalises a header cell: underscores and most dots become spaces and
// the result is upper-cased.
func title(name string) string {
	origLen := len(name)
	rs := []rune(name)
	for i, r := range rs {
		switch r {
		case '_':
			rs[i] = ' '
		case '.':
			if (i != 0 && !isNumOrSpace(rs[i-1])) || (i != len(rs)-1 && !isNumOrSpace(rs[i+1])) {
				rs[i] = ' '
			}
		}
	}
	name = strings.TrimSpace(string(rs))
	if len(name) == 0 && origLen > 0 {
		name = " "
	}
	return strings.ToUpper(name)
}

func isNumOrSpace(r rune) bool {
	return ('0' <= r && r <= '9') || r == ' '
}

func displayWidth(s string) int {
	return textwidth.StringWidth(ansiEscape.ReplaceAllLiteralString(s, ""))
}

func padCenter(s string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		left := gap / 2
		right := gap - left
		return strings.Repeat(space, left) + s + strings.Repeat(space, right)
	}
	return s
}

func padRight(s string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		return s + strings.Repeat(space, gap)
	}
	return s
}

func padLeft(s string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		return strings.Repeat(space, gap) + s
	}
	return s
}

// wrapString splits s into lines of at most lim cells with minimal
// raggedness. A single word longer than lim raises the limit.
func wrapString(s string, lim int) []string {
	words := strings.Split(s, space)
	for _, w := range words {
		if ww := textwidth.StringWidth(w); ww > lim {
			lim = ww
		}
	}
	var lines []string
	for _, line := range wrapWords(words, 1, lim, wrapPenalty) {
		lines = append(lines, strings.Join(line, space))
	}
	return lines
}

// wrapWords implements the minimum raggedness line breaking algorithm. Each
// line costs the square of its unused cells; lines longer than lim pay an
// additional penalty of pen. The last line is free when it fits.
func wrapWords(words []string, spc, lim, pen int) [][]string {
	n := len(words)
	length := make([][]int, n)
	for i := 0; i < n; i++ {
		length[i] = make([]int, n)
		length[i][i] = textwidth.StringWidth(words[i])
		for j := i + 1; j < n; j++ {
			length[i][j] = length[i][j-1] + spc + textwidth.StringWidth(words[j])
		}
	}
	nbrk := make([]int, n)
	cost := make([]int, n)
	for i := range cost {
		cost[i] = 1<<31 - 1
	}
	for i := n - 1; i >= 0; i-- {
		if length[i][n-1] <= lim || i == n-1 {
			cost[i] = 0
			nbrk[i] = n
			continue
		}
		for j := i + 1; j < n; j++ {
			d := lim - length[i][j-1]
			c := d*d + cost[j]
			if length[i][j-1] > lim {
				c += pen
			}
