// Package runner wires the JSON input to the rendered table.
package runner

import (
	"encoding/json"
	"fmt"
	"io"

	"github.com/psampaz/go-mod-outdated/internal/mod"
	"github.com/psampaz/go-mod-outdated/internal/table"
)

// StyleMarkdown selects a Markdown compatible table.
const StyleMarkdown = "markdown"

// Run reads a stream of JSON module objects from in, drops the main module
// and the modules excluded by the update/direct filters, and writes the
// remaining ones as a table to out. Nothing is written when no module is
// left.
//
// It returns true when ci is set and at least one listed module is outdated,
// and a non-nil error when the input could not be decoded.
func Run(in io.Reader, out io.Writer, update, direct, ci bool, style string) (bool, error) {
	var modules []mod.Module
	dec := json.NewDecoder(in)
	for {
		var m mod.Module
		err := dec.Decode(&m)
		if err == io.EOF {
			break
		}
		if err != nil {
			return false, err
		}
		modules = append(modules, m)
	}

	filtered := filter(modules, update, direct)
	if len(filtered) == 0 {
		return false, nil
	}
	renderTable(out, filtered, style)

	if ci {
		for _, m := range filtered {
			if m.IsOutdated() {
				return true, nil
			}
		}
	}
	return false, nil
}

func filter(modules []mod.Module, update, direct bool) []mod.Module {
	var out []mod.Module
	for _, m := range modules {
		if m.Main {
			continue
		}
		if update && !m.HasUpdate() {
			continue
		}
		if direct && m.Indirect {
			continue
		}
		out = append(out, m)
	}
	return out
}

func renderTable(out io.Writer, modules []mod.Module, style string) {
	t := table.New(out)
	t.SetHeader([]string{"Module", "Version", "New Version", "Direct", "Valid Timestamps"})
	if style == StyleMarkdown {
		t.SetBorders(table.Borders{Left: true, Right: true, Top: false, Bottom: false})
		t.SetCenterSeparator("|")
	}
	for i := range modules {
		m := &modules[i]
		t.Append([]string{
			m.Path,
			m.CurrentVersion(),
			m.NewVersion(),
			fmt.Sprintf("%t", !m.Indirect),
			fmt.Sprintf("%t", !m.InvalidTimestamp()),
		})
	}
	t.Render()
}
