// Package mod models the entries printed by "go list -u -m -json all".
package mod

import "time"

// Module mirrors the JSON structure emitted by the go command for a module.
type Module struct {
	Path      string       // module path
	Version   string       // module version
	Replace   *Module      // replaced by this module
	Time      *time.Time   // time version was created
	Update    *Module      // available update, if any
	Main      bool         // is this the main module?
	Indirect  bool         // is this module only an indirect dependency?
	Dir       string       // directory holding files for this module, if any
	GoMod     string       // path to go.mod file for this module, if any
	GoVersion string       // go version used in module
	Error     *ModuleError // error loading module
}

// ModuleError holds the error text reported for a module.
type ModuleError struct {
	Err string // the error itself
}

// effective returns the module that actually gets used: the replacement when
// one is configured, the module itself otherwise.
func (m *Module) effective() *Module {
	if m.Replace != nil {
		return m.Replace
	}
	return m
}

// InvalidTimestamp reports whether the available update is older than the
// version currently in use, which hints at a bogus version tag.
func (m *Module) InvalidTimestamp() bool {
	if e := m.effective(); e.Time != nil && e.Update != nil {
		return e.Time.After(*e.Update.Time)
	}
	return false
}

// CurrentVersion returns the version in use, taking replacements into account.
func (m *Module) CurrentVersion() string {
	return m.effective().Version
}

// NewVersion returns the version of the available update, or an empty string.
func (m *Module) NewVersion() string {
	e := m.effective()
	if e.Update == nil {
		return ""
	}
	return e.Update.Version
}

// HasUpdate reports whether the module itself lists an available update.
func (m *Module) HasUpdate() bool {
	return m.Update != nil
}

// IsOutdated reports whether an update is available for the module in use.
func (m *Module) IsOutdated() bool {
	return m.effective().Update != nil
}
EOF
cat > internal/runner/runner.go <<'EOF'
// Package runner wires the JSON input to the rendered table.
package runner

import (
	"encoding/json"
	"fmt"
	"io"

	"github.com/psampaz/go-mod-outdated/internal/mod"
	"github.com/psampaz/go-mod-outdated/internal/table"
)

// StyleMarkdown selects a Markdown compatible table.
const StyleMarkdown = "markdown"

// Run reads a stream of JSON module objects from in, drops the main module
// and the modules excluded by the update/direct filters, and writes the
// remaining ones as a table to out. Nothing is written when no module is
// left.
//
// It returns true when ci is set and at least one listed module is outdated,
// and a non-nil error when the input could not be decoded.
func Run(in io.Reader, out io.Writer, update, direct, ci bool, style string) (bool, error) {
	var modules []mod.Module
	dec := json.NewDecoder(in)
	for {
		var m mod.Module
		err := dec.Decode(&m)
		if err == io.EOF {
			break
		}
		if err != nil {
			return false, err
		}
		modules = append(modules, m)
	}

	filtered := filter(modules, update, direct)
	if len(filtered) == 0 {
		return false, nil
	}
	renderTable(out, filtered, style)

	if ci {
		for _, m := range filtered {
			if m.IsOutdated() {
				return true, nil
			}
		}
	}
	return false, nil
}

func filter(modules []mod.Module, update, direct bool) []mod.Module {
	var out []mod.Module
	for _, m := range modules {
		if m.Main {
			continue
		}
		if update && !m.HasUpdate() {
			continue
		}
		if direct && m.Indirect {
			continue
		}
		out = append(out, m)
	}
	return out
}

func renderTable(out io.Writer, modules []mod.Module, style string) {
	t := table.New(out)
	t.SetHeader([]string{"Module", "Version", "New Version", "Direct", "Valid Timestamps"})
	if style == StyleMarkdown {
		t.SetBorders(table.Borders{Left: true, Right: true, Top: false, Bottom: false})
		t.SetCenterSeparator("|")
	}
	for i := range modules {
		m := &modules[i]
		t.Append([]string{
			m.Path,
			m.CurrentVersion(),
			m.NewVersion(),
			fmt.Sprintf("%t", !m.Indirect),
			fmt.Sprintf("%t", !m.InvalidTimestamp()),
		})
	}
	t.Render()
}
EOF
